import * as NodePath from "node:path";
import { build } from "vite-plus";
export async function generate(feature: string, name: string) {
  const stem = name.toLowerCase() + "-stream";
  return build({ configFile: false, build: { lib: {
    entry: NodePath.join(".", "src/features", feature, `${stem}.browser.ts`),
    formats: ["iife"]
  } } });
}
